import{config}from'./config.js';import{dictionaries}from'./copy.js';import{safeAsset,translate}from'./site-runtime.js';
let token=null,refreshToken=null,refreshTimer,settings={},products=[],pages=[],panel='overview',donationPage=0,orderPage=0,editingProduct=null,editingPage=null,editingOrder=null,blocks=[];
const pageSize=20,$=id=>document.getElementById(id),money=cents=>new Intl.NumberFormat('pt-PT',{style:'currency',currency:'EUR'}).format(cents/100),publicHeaders={apikey:config.supabasePublishableKey,'Content-Type':'application/json'};
const panels={overview:'Visão geral',donations:'Doações',orders:'Pedidos',catalog:'Planos e produtos',content:'Textos do site',pages:'Páginas',visual:'Imagens e aparência',marketing:'Pixels e tags',conditions:'Condições e valores',organisation:'Organização',account:'A minha conta'};
function error(message,auth=false){const el=$(auth?'auth-error':'admin-error');el.textContent=message;el.hidden=false;}
function feedback(message){$('global-message').textContent=message;$('global-message').hidden=false;setTimeout(()=>{$('global-message').hidden=true;},5000);}
async function rest(path,method='GET',body){const response=await fetch(`${config.supabaseUrl}/rest/v1/${path}`,{method,headers:{...publicHeaders,Authorization:`Bearer ${token}`,Prefer:'count=exact,return=representation'},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(20000)});const text=await response.text();if(!response.ok){let code;try{code=JSON.parse(text).code;}catch{}throw new Error(code==='23514'?'Preencha os dados públicos e confirme a revisão das políticas antes de abrir pagamentos.':response.status===401?'Sessão expirada. Entre novamente.':'Não foi possível guardar. Verifique os dados e permissões.');}return{data:text?JSON.parse(text):null,total:Number(response.headers.get('content-range')?.split('/')[1])||0};}
async function patchSettings(change){await rest('campaign_settings?id=eq.true','PATCH',{...change,updated_at:new Date().toISOString()});Object.assign(settings,change);feedback('Alterações guardadas.');}
function valueForm(id,value){for(const input of $(id).elements){if(!input.name)continue;if(input.type==='checkbox')input.checked=value[input.name]===true;else input.value=value[input.name]??'';}}
function rawForm(id){const values={};for(const input of $(id).elements)if(input.name)values[input.name]=input.type==='checkbox'?input.checked:input.value.trim();return values;}
function submit(id,callback){$(id).addEventListener('submit',async event=>{event.preventDefault();$('admin-error').hidden=true;const button=event.target.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=true;try{await callback(rawForm(id));}catch(e){error(e.message);}finally{if(button)button.disabled=false;}});}
function scheduleRefresh(expires){clearTimeout(refreshTimer);refreshTimer=setTimeout(async()=>{try{const response=await fetch(`${config.supabaseUrl}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:publicHeaders,body:JSON.stringify({refresh_token:refreshToken})});if(!response.ok)throw new Error();const data=await response.json();token=data.access_token;refreshToken=data.refresh_token;scheduleRefresh(data.expires_in);}catch{logout();error('A sessão expirou.',true);}},Math.max(60,expires-90)*1000);}
function logout(){token=null;refreshToken=null;clearTimeout(refreshTimer);$('admin-dashboard').hidden=true;$('auth-screen').hidden=false;$('admin-password').value='';}
$('admin-login').addEventListener('submit',async event=>{event.preventDefault();$('auth-error').hidden=true;const button=event.target.querySelector('button');button.disabled=true;try{const response=await fetch(`${config.supabaseUrl}/auth/v1/token?grant_type=password`,{method:'POST',headers:publicHeaders,body:JSON.stringify({email:$('admin-email').value.trim(),password:$('admin-password').value}),signal:AbortSignal.timeout(15000)});if(!response.ok)throw new Error('Email ou palavra-passe inválidos.');const data=await response.json();token=data.access_token;refreshToken=data.refresh_token;const membership=await rest(`admin_members?user_id=eq.${data.user.id}&select=user_id`);if(!membership.data.length){logout();throw new Error('Esta conta não é administradora.');}$('auth-screen').hidden=true;$('admin-dashboard').hidden=false;$('admin-user').textContent=data.user.email;$('admin-password').value='';scheduleRefresh(data.expires_in);await loadAll();}catch(e){error(e.message,true);}finally{button.disabled=false;}});
$('bootstrap-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;try{const response=await fetch(`${config.apiBase}/bootstrap-admin`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:$('bootstrap-code').value.trim(),email:$('bootstrap-email').value.trim(),password:$('bootstrap-password').value}),signal:AbortSignal.timeout(25000)});if(!response.ok)throw new Error('Não foi possível criar o acesso. Verifique o código ou use uma conta já autorizada.');$('admin-email').value=$('bootstrap-email').value.trim();$('admin-password').value=$('bootstrap-password').value;event.target.reset();$('bootstrap-panel').open=false;error('Acesso criado. Clique em “Entrar no painel”.',true);}catch(e){error(e.message,true);}finally{button.disabled=false;}});
$('admin-logout').addEventListener('click',async()=>{const previous=token;logout();if(previous)try{await fetch(`${config.supabaseUrl}/auth/v1/logout`,{method:'POST',headers:{...publicHeaders,Authorization:`Bearer ${previous}`}});}catch{}});
$('admin-nav').addEventListener('click',async e=>{const button=e.target.closest('[data-panel]');if(!button)return;panel=button.dataset.panel;document.querySelectorAll('[data-admin-panel]').forEach(s=>s.hidden=s.dataset.adminPanel!==panel);document.querySelectorAll('[data-panel]').forEach(b=>b.classList.toggle('active',b===button));$('panel-title').textContent=panels[panel];try{if(panel==='donations')await loadDonations();if(panel==='orders')await loadOrders();}catch(err){error(err.message);}});
$('refresh-admin').addEventListener('click',()=>loadAll().catch(e=>error(e.message)));
async function loadAll(){settings=(await rest('campaign_settings?id=eq.true&select=*')).data[0];products=(await rest('catalog_products?select=*&order=sort_order.asc,created_at.desc')).data;pages=(await rest('site_pages?select=*&order=sort_order.asc')).data;const[{data:stats},{data:sales}]=await Promise.all([rest('rpc/admin_donation_summary','POST',{}),rest('rpc/admin_order_summary','POST',{})]);$('metric-total').textContent=money(stats.net_received_cents);$('metric-gifts').textContent=stats.confirmed_gifts;$('metric-monthly').textContent=stats.active_monthly;$('metric-sales').textContent=money(sales.net_sales_cents);$('readiness').textContent=`Doações: ${settings.donations_enabled?'abertas':'fechadas'} · Loja: ${settings.shop_enabled?'aberta':'fechada'} · Complete os dados públicos em Organização e ajuste o domínio antes da campanha.`;renderProducts();renderPages();renderContent();renderVisual();loadForms();if(panel==='donations')await loadDonations();if(panel==='orders')await loadOrders();}
function loadForms(){valueForm('organisation-form',{...settings,reports:(settings.reports||[]).map(r=>`${r.title} | ${r.url}`).join('\n')});valueForm('marketing-form',{...settings.tracking_settings,canonical_url:settings.canonical_url,extra_scripts:(settings.tracking_settings.extra_scripts||[]).map(x=>x.src).join('\n')});valueForm('conditions-form',{...settings,donation_min:settings.donation_min_cents/100,donation_max:settings.donation_max_cents/100,quick_amounts:settings.quick_amounts_cents.map(x=>x/100).join(','),shipping:settings.shipping_cents/100,shipping_countries:settings.shipping_countries.join(',')});}
async function loadDonations(){const filter=$('status-filter').value;const{data,total}=await rest(`donations?select=created_at,donor_name,donor_email,amount_cents,frequency,status,livemode,updates_opt_in&order=created_at.desc&limit=${pageSize}&offset=${donationPage*pageSize}${filter==='all'?'':`&status=eq.${filter}`}`);tableRows('donation-rows',data.map(d=>[new Date(d.created_at).toLocaleString('pt-PT'),d.donor_name||'—',d.donor_email||'—',money(d.amount_cents),d.frequency==='monthly'?'Mensal':'Única',d.status,d.livemode?'Live':'Teste',d.updates_opt_in?'Sim':'Não']));pager('page-info','previous-page','next-page',donationPage,total);}
function tableRows(id,rows){$(id).replaceChildren();for(const row of rows){const tr=document.createElement('tr');for(const value of row){const td=document.createElement('td');if(value instanceof HTMLElement)td.append(value);else td.textContent=String(value);tr.append(td);}$(id).append(tr);}}
function pager(id,previous,next,current,total){$(id).textContent=`Página ${current+1} de ${Math.max(1,Math.ceil(total/pageSize))} · ${total} registos`;$(previous).disabled=current===0;$(next).disabled=(current+1)*pageSize>=total;}
$('status-filter').addEventListener('change',()=>{donationPage=0;loadDonations().catch(e=>error(e.message));});$('previous-page').addEventListener('click',()=>{donationPage=Math.max(0,donationPage-1);loadDonations().catch(e=>error(e.message));});$('next-page').addEventListener('click',()=>{donationPage++;loadDonations().catch(e=>error(e.message));});
async function loadOrders(){const{data,total}=await rest(`shop_orders?select=*&order=created_at.desc&limit=${pageSize}&offset=${orderPage*pageSize}`);tableRows('order-rows',data.map(o=>{const b=document.createElement('button');b.className='admin-table-button';b.textContent='Ver pedido';b.addEventListener('click',()=>openOrder(o).catch(e=>error(e.message)));return[new Date(o.created_at).toLocaleString('pt-PT'),o.donor_email||'—',money(o.amount_cents),o.status,o.fulfillment_status,o.livemode?'Live':'Teste',b];}));pager('order-page-info','order-previous','order-next',orderPage,total);}
$('order-previous').addEventListener('click',()=>{orderPage=Math.max(0,orderPage-1);loadOrders().catch(e=>error(e.message));});$('order-next').addEventListener('click',()=>{orderPage++;loadOrders().catch(e=>error(e.message));});
async function openOrder(order){editingOrder=order;const{data:items}=await rest(`shop_order_items?order_id=eq.${order.id}&select=*`);const box=document.createElement('div');box.className='order-summary';box.textContent=`${order.id}\n${order.donor_name||''} · ${order.donor_email||''}\n${money(order.amount_cents)} · ${order.status}\n\n${items.map(i=>`${i.quantity} × ${i.title} — ${money(i.unit_price_cents)}`).join('\n')}\n\n${order.shipping_details?JSON.stringify(order.shipping_details,null,2):'Sem endereço de entrega física.'}`;$('order-details').replaceChildren(box);if(order.stripe_payment_intent_id){const a=document.createElement('a');a.className='text-link';a.href=`https://dashboard.stripe.com/${order.livemode?'':'test/'}payments/${encodeURIComponent(order.stripe_payment_intent_id)}`;a.target='_blank';a.rel='noopener';a.textContent='Ver pagamento e reembolsos na Stripe ↗';$('order-details').append(a);}valueForm('order-form',order);$('order-dialog').showModal();}
submit('order-form',async values=>{await rest(`shop_orders?id=eq.${editingOrder.id}`,'PATCH',values);$('order-dialog').close();feedback('Entrega atualizada.');await loadOrders();});
const names={support_once:'Doação única',support_monthly:'Plano mensal',physical:'Produto físico',digital:'Produto digital'};
function renderProducts(){$('admin-products').replaceChildren();for(const product of products){const card=document.createElement('article');card.className='admin-product-card';const image=safeAsset(product.image_url);if(image){const img=document.createElement('img');img.src=image;img.alt=translate(product.title,'pt');card.append(img);}const body=document.createElement('div'),h=document.createElement('h3'),p=document.createElement('p'),price=document.createElement('strong'),actions=document.createElement('div');h.textContent=translate(product.title,'pt');p.textContent=`${names[product.kind]} · ${product.published?'Publicado':'Rascunho'}${product.stock===null?'':` · ${product.stock} disponíveis`}`;price.textContent=money(product.price_cents)+(product.kind==='support_monthly'?' / mês':'');actions.className='admin-card-actions';for(const[label,callback]of[['Editar',()=>openProduct(product)],[product.published?'Ocultar':'Publicar',async()=>{await rest(`catalog_products?id=eq.${product.id}`,'PATCH',{published:!product.published});await loadAll();}]]){const b=document.createElement('button');b.className='button button-outline button-small';b.textContent=label;b.addEventListener('click',()=>Promise.resolve(callback()).catch(e=>error(e.message)));actions.append(b);}body.append(h,p,price,actions);card.append(body);$('admin-products').append(card);}}
function openProduct(product=null){editingProduct=product;$('product-form').reset();const other={};if(product)for(const language of['de','fr','es'])if(product.title[language]||product.description[language])other[language]={title:product.title[language]||'',description:product.description[language]||''};valueForm('product-form',product?{...product,price:product.price_cents/100,title_en:product.title.en,title_pt:product.title.pt||'',description_en:product.description.en||'',description_pt:product.description.pt||'',translations_json:Object.keys(other).length?JSON.stringify(other,null,2):''}:{kind:'support_once',price:25,sort_order:0,published:false});$('product-error').hidden=true;$('product-dialog').showModal();}
$('new-product').addEventListener('click',()=>openProduct());
$('product-form').addEventListener('submit',async event=>{event.preventDefault();try{const v=rawForm('product-form'),title={en:v.title_en},description={en:v.description_en};if(v.title_pt)title.pt=v.title_pt;if(v.description_pt)description.pt=v.description_pt;if(v.translations_json)for(const[language,copy]of Object.entries(JSON.parse(v.translations_json)))if(['de','fr','es'].includes(language)){title[language]=copy.title;description[language]=copy.description;}const price=Math.round(Number(v.price)*100);if(v.kind.startsWith('support_')&&(price<settings.donation_min_cents||price>settings.donation_max_cents))throw new Error('O preço do apoio precisa estar dentro dos limites de doação.');const body={kind:v.kind,title,description,price_cents:price,image_url:v.image_url||null,category:v.category||null,stock:v.stock===''?null:Number(v.stock),download_url:v.download_url||null,published:v.published,sort_order:Number(v.sort_order)||0,updated_at:new Date().toISOString()};await rest(editingProduct?`catalog_products?id=eq.${editingProduct.id}`:'catalog_products',editingProduct?'PATCH':'POST',body);$('product-dialog').close();feedback('Item guardado.');await loadAll();}catch(e){$('product-error').textContent=e.message;$('product-error').hidden=false;}});
async function upload(file){if(!file)return null;if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type)||file.size>10000000)throw new Error('Use PNG, JPG, WebP ou GIF até 10 MB.');const ext={'image/png':'png','image/jpeg':'jpg','image/webp':'webp','image/gif':'gif'}[file.type],name=`${Date.now()}-${crypto.randomUUID()}.${ext}`;const response=await fetch(`${config.supabaseUrl}/storage/v1/object/site-media/${name}`,{method:'POST',headers:{apikey:config.supabasePublishableKey,Authorization:`Bearer ${token}`,'Content-Type':file.type},body:file,signal:AbortSignal.timeout(30000)});if(!response.ok)throw new Error('Não foi possível enviar a imagem.');return `${config.supabaseUrl}/storage/v1/object/public/site-media/${name}`;}
$('product-image-upload').addEventListener('change',async e=>{try{const url=await upload(e.target.files[0]);if(url)$('product-form').elements.image_url.value=url;}catch(err){$('product-error').textContent=err.message;$('product-error').hidden=false;}});
function renderContent(){const language=$('content-language').value,search=$('content-search').value.toLowerCase();$('content-fields').replaceChildren();for(const[key,text]of Object.entries(dictionaries[language])){if(search&&!`${key} ${text}`.toLowerCase().includes(search))continue;const box=document.createElement('div');box.className='content-field';const label=document.createElement('label');label.textContent=key;const textarea=document.createElement('textarea');textarea.dataset.contentKey=key;textarea.rows=text.length>180?4:2;textarea.placeholder=text;textarea.value=settings.content_overrides?.[language]?.[key]||'';textarea.addEventListener('input',()=>{settings.content_overrides[language]||={};if(textarea.value)settings.content_overrides[language][key]=textarea.value;else delete settings.content_overrides[language][key];});box.append(label,textarea);$('content-fields').append(box);}}
$('content-language').addEventListener('change',renderContent);$('content-search').addEventListener('input',renderContent);$('save-content').addEventListener('click',()=>patchSettings({content_overrides:settings.content_overrides}).catch(e=>error(e.message)));
function renderVisual(){valueForm('visual-form',{brand:settings.brand,tagline:settings.tagline,primary:settings.visual_settings.primary||'#174d43',background:settings.visual_settings.background||'#faf8f2',text:settings.visual_settings.text||'#243a33',accent:settings.visual_settings.accent||'#f1bf80',heading_font:settings.visual_settings.heading_font||'serif'});$('media-fields').replaceChildren();for(const[key,label]of[['logo','Logo'],['hero','Hero principal'],['food','Alimentação'],['vet','Veterinário'],['care','Cuidados / missão']]){const box=document.createElement('div'),l=document.createElement('label'),input=document.createElement('input'),file=document.createElement('input');l.textContent=label;input.name=`media_${key}`;input.value=typeof settings.media_settings[key]==='string'?settings.media_settings[key]:settings.media_settings[key]?.url||'';input.placeholder=key==='logo'?'/assets/logo.svg':`/assets/${key}.webp`;file.type='file';file.accept='image/png,image/jpeg,image/webp,image/gif';file.addEventListener('change',async e=>{try{const url=await upload(e.target.files[0]);if(url)input.value=url;}catch(err){error(err.message);}});l.append(input);box.append(l,file);$('media-fields').append(box);}$('section-fields').replaceChildren();for(const[key,label]of[['hero','Hero'],['care','Como ajudar'],['mission','Missão'],['plans','Planos'],['donate','Doação'],['transparency','Transparência'],['other-help','Outras ajudas'],['faq','Perguntas'],['closing','Convite final']]){const l=document.createElement('label');l.className='checkbox-row';const c=document.createElement('input');c.type='checkbox';c.name=`section_${key}`;c.checked=settings.section_settings[key]!==false;l.append(c,document.createTextNode(label));$('section-fields').append(l);}}
submit('visual-form',async values=>{const media={...settings.media_settings},sections={...settings.section_settings};for(const[key,value]of Object.entries(values)){if(key.startsWith('media_'))media[key.slice(6)]=value;if(key.startsWith('section_'))sections[key.slice(8)]=value;}await patchSettings({brand:values.brand,tagline:values.tagline,media_settings:media,section_settings:sections,visual_settings:{primary:values.primary,background:values.background,text:values.text,accent:values.accent,heading_font:values.heading_font}});});
submit('marketing-form',async v=>{const extra=v.extra_scripts.split('\n').map(x=>x.trim()).filter(Boolean).map(src=>{if(!src.startsWith('https://'))throw new Error('Scripts adicionais devem usar HTTPS.');return{src};});await patchSettings({canonical_url:v.canonical_url||null,tracking_settings:{google_tag_id:v.google_tag_id,google_ads_conversion_label:v.google_ads_conversion_label,ga4_id:v.ga4_id,gtm_id:v.gtm_id,meta_pixel_id:v.meta_pixel_id,extra_scripts:extra}});});
submit('organisation-form',async v=>{const reports=v.reports.split('\n').filter(x=>x.trim()).map(line=>{const[title,...url]=line.split('|');return{title:title.trim(),url:url.join('|').trim()};});delete v.reports;await patchSettings({...v,reports});});
submit('conditions-form',async v=>{const countries=[...new Set(v.shipping_countries.toUpperCase().split(',').map(x=>x.trim()).filter(Boolean))];if(countries.some(x=>!/^\w{2}$/.test(x)))throw new Error('Use códigos de países com duas letras.');await patchSettings({donation_min_cents:Math.round(Number(v.donation_min)*100),donation_max_cents:Math.round(Number(v.donation_max)*100),quick_amounts_cents:v.quick_amounts.split(',').map(x=>Math.round(Number(x.trim())*100)).filter(x=>x>0),terms_version:v.terms_version,monthly_enabled:v.monthly_enabled,donations_enabled:v.donations_enabled,shipping_cents:Math.round(Number(v.shipping)*100),shipping_countries:countries,shop_enabled:v.shop_enabled,automatic_tax_enabled:v.automatic_tax_enabled,shop_policy:v.shop_policy});});
function renderPages(){$('admin-pages').replaceChildren();for(const page of pages){const row=document.createElement('div');row.className='page-row';const info=document.createElement('div'),h=document.createElement('h3'),p=document.createElement('p'),actions=document.createElement('div');h.textContent=translate(page.title,'pt')||page.slug;p.textContent=`/${page.slug} · ${page.published?'Publicada':'Rascunho'}`;info.append(h,p);const edit=document.createElement('button');edit.className='button button-outline button-small';edit.textContent='Editar';edit.addEventListener('click',()=>openPage(page));const view=document.createElement('a');view.className='button button-outline button-small';view.textContent='Ver';view.href=`/page.html?slug=${page.slug}&lang=pt`;view.target='_blank';view.rel='noopener';actions.append(edit,view);row.append(info,actions);$('admin-pages').append(row);}}
function openPage(page=null){editingPage=page;blocks=structuredClone(page?.blocks||[{type:'text',text:{en:'',pt:''}}]);$('page-form').reset();valueForm('page-form',page?{...page,title_en:page.title.en||'',title_pt:page.title.pt||''}:{published:false,show_in_navigation:false});renderBlocksEditor();$('page-error').hidden=true;$('page-dialog').showModal();}
$('new-page').addEventListener('click',()=>openPage());$('add-page-block').addEventListener('click',()=>{blocks.push({type:'text',text:{en:'',pt:''}});renderBlocksEditor();});
function renderBlocksEditor(){$('page-block-editor').replaceChildren();blocks.forEach((block,index)=>{const card=document.createElement('div');card.className='page-block-card';const toolbar=document.createElement('div');toolbar.className='page-block-toolbar';const select=document.createElement('select');for(const[k,label]of[['text','Texto'],['heading','Título'],['image','Imagem'],['button','Botão']]){const o=document.createElement('option');o.value=k;o.textContent=label;select.append(o);}select.value=block.type;select.addEventListener('change',()=>{block.type=select.value;renderBlocksEditor();});const remove=document.createElement('button');remove.type='button';remove.className='icon-button';remove.textContent='×';remove.addEventListener('click',()=>{blocks.splice(index,1);renderBlocksEditor();});toolbar.append(select,remove);card.append(toolbar);for(const[language,label]of[['en','Texto em inglês'],['pt','Texto em português']]){const l=document.createElement('label');l.textContent=block.type==='image'?`Descrição da imagem (${language})`:label;const input=document.createElement('textarea');input.rows=block.type==='text'?3:1;const key=block.type==='image'?'alt':'text';input.value=typeof block[key]==='string'?block[key]:block[key]?.[language]||'';input.addEventListener('input',()=>{if(typeof block[key]!=='object')block[key]={};block[key][language]=input.value;});l.append(input);card.append(l);}if(['image','button'].includes(block.type)){const l=document.createElement('label');l.textContent='URL';const input=document.createElement('input');input.value=block.url||'';input.addEventListener('input',()=>{block.url=input.value;});l.append(input);card.append(l);}$('page-block-editor').append(card);});}
$('page-form').addEventListener('submit',async event=>{event.preventDefault();try{const v=rawForm('page-form'),body={slug:v.slug,title:{en:v.title_en,...(v.title_pt?{pt:v.title_pt}:{})},blocks:v.blocks_json?JSON.parse(v.blocks_json):blocks,published:v.published,show_in_navigation:v.show_in_navigation,updated_at:new Date().toISOString()};if(!Array.isArray(body.blocks))throw new Error('Blocos devem ser uma lista.');await rest(editingPage?`site_pages?id=eq.${editingPage.id}`:'site_pages',editingPage?'PATCH':'POST',body);$('page-dialog').close();feedback('Página guardada.');await loadAll();}catch(e){$('page-error').textContent=e.message;$('page-error').hidden=false;}});
submit('password-form',async()=>{const response=await fetch(`${config.supabaseUrl}/auth/v1/user`,{method:'PUT',headers:{...publicHeaders,Authorization:`Bearer ${token}`},body:JSON.stringify({password:$('new-password').value})});if(!response.ok)throw new Error('Não foi possível alterar a palavra-passe.');$('password-form').reset();feedback('Palavra-passe alterada.');});
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>$(b.dataset.close).close()));
